+/** Theoretical use from sales vs actual consume movements per item between two days (inclusive). */
+export function varianceReport(store, from, to) {
+  const theoreticalByItem = new Map();
+  const sales = store.data.sales ?? [];
+  const salesTickets = new Set(sales.map((s) => s.ticket));
+  for (const s of sales) {
+    const day = dayOf(s.soldAt);
+    if (day < from || day > to) continue;
+    const dish = (store.data.dishes ?? []).find((d) => d.id === s.dishId);
+    if (!dish) continue;
+    const recipe = store.data.recipes.find((r) => r.id === dish.recipeId);
+    if (!recipe) continue;
+    for (const n of scaled(recipe, s.qty)) {
+      theoreticalByItem.set(n.itemId, Math.round(((theoreticalByItem.get(n.itemId) ?? 0) + n.qty) * 1000) / 1000);
+    }
+  }
+  const batchItem = new Map(store.data.batches.map((b) => [b.id, b.itemId]));
+  const actualByItem = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || m.qty <= 0) continue;
+    const day = dayOf(m.at);
+    if (day < from || day > to) continue;
+    const itemId = batchItem.get(m.batchId);
+    if (itemId === undefined) continue;
+    actualByItem.set(itemId, Math.round(((actualByItem.get(itemId) ?? 0) + m.qty) * 1000) / 1000);
+    if (typeof m.ref === "string" && m.ref.startsWith("sale:") && !salesTickets.has(m.ref.slice(5))) {
+      theoreticalByItem.set(itemId, Math.round(((theoreticalByItem.get(itemId) ?? 0) + m.qty) * 1000) / 1000);
+    }
+  }
+  return listItems(store)
+    .map((item) => {
+      const theoretical = theoreticalByItem.get(item.id) ?? 0;
+      const actual = actualByItem.get(item.id) ?? 0;
+      const diff = Math.round((actual - theoretical) * 1000) / 1000;
+      return { itemId: item.id, theoretical, actual, diff };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
